import jakarta.ws.rs.core.*;
import jakarta.ws.rs.ext.*;

class Missing extends RuntimeException {
    Missing(String m) {
        super(m);
    }
}

record ApiError(String code, String message) { }

@Provider
class MissingMapper implements ExceptionMapper<Missing> {
    public Response toResponse(Missing e) {
        return Response.status(404).entity(new ApiError("NOT_FOUND", e.getMessage())).build();
    }
}

public class MapperSample {
    public static void main(String[] a) {
        Response r = new MissingMapper().toResponse(new Missing("ありません"));
        System.out.println(r.getStatus() + " " + r.getEntity());
    }
}

