        Scanner sc = new Scanner(System.in);
        String caller = sc.next(), role = sc.next(), owner = sc.next();
        if (caller.equals("-")) {
            System.out.println("401 Unauthorized");
            return;
        }
        boolean allowed = role.equals("admin") || (role.equals("user") && caller.equals(owner));
        System.out.println(allowed ? "200 OK" : "403 Forbidden");
    }
}

